private class MessagesPigeonStreamHandler<T>(
    val wrapper: MessagesPigeonEventChannelWrapper<T>
) : EventChannel.StreamHandler {
  var pigeonSink: PigeonEventSink<T>? = null

  override fun onListen(p0: Any?, sink: EventChannel.EventSink) {
    pigeonSink = PigeonEventSink<T>(sink)
    wrapper.onListen(p0, pigeonSink!!)
  }

  override fun onCancel(p0: Any?) {
    pigeonSink = null
    wrapper.onCancel(p0)
  }
}

interface MessagesPigeonEventChannelWrapper<T> {
  open fun onListen(p0: Any?, sink: PigeonEventSink<T>) {}

  open fun onCancel(p0: Any?) {}
}

class PigeonEventSink<T>(private val sink: EventChannel.EventSink) {
  fun success(value: T) {
    sink.success(value)
  }

  fun error(errorCode: String, errorMessage: String?, errorDetails: Any?) {
    sink.error(errorCode, errorMessage, errorDetails)
  }

  fun endOfStream() {
    sink.endOfStream()
  }
}
      
/**
 * Native-to-Dart streams. One channel carries every poll's statuses, tagged with their
 * [PollingEventMessage.pollId]: Pigeon's event-channel methods take no parameters, and a
 * channel per poll would need registering and tearing down natively for each one.
 */
abstract class PollingEventsStreamHandler : MessagesPigeonEventChannelWrapper<PollingEventMessage> {
  companion object {
    fun register(messenger: BinaryMessenger, streamHandler: PollingEventsStreamHandler, instanceName: String = "") {
      var channelName: String = "dev.flutter.pigeon.ping_davinci.PingDaVinciEventApi.pollingEvents"
      if (instanceName.isNotEmpty()) {
        channelName += ".$instanceName"
      }
      val internalStreamHandler = MessagesPigeonStreamHandler<PollingEventMessage>(streamHandler)
      EventChannel(messenger, channelName, MessagesPigeonMethodCodec).setStreamHandler(internalStreamHandler)
    }
  }
// Implement methods from MessagesPigeonEventChannelWrapper
override fun onListen(p0: Any?, sink: PigeonEventSink<PollingEventMessage>) {}

override fun onCancel(p0: Any?) {}
}
      
